  src:url("шрифти/KyivTypeTitling-VarGX.ttf") format("truetype")}
@font-face{font-family:"KyivType Serif";font-style:normal;font-weight:1 1000;font-display:swap;
  src:url("шрифти/KyivTypeSerif-VarGX.ttf") format("truetype")}


:root{
  color-scheme:light;
  --полотно:#F4F0E8;    
  --аркуш:#FBF9F4;      
  --папір:#EDE7DA;      
  --чорнило:#1B1A17;    
  --олівець:#6B665C;
  --межа:#E0D9CB;
  --межа-темна:#C4BBA6;
  --золото:#846426;     
  --золото-2:#B79340;
  --на-золоті:#FBF9F4;
  --сигнал:#A6452F;     
  --фото-тло:#fff;      

  --фактура:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'><g fill='none' stroke='%231B1A17' stroke-opacity='.06'><path d='M16 3l2.6 10.4L29 16l-10.4 2.6L16 29l-2.6-10.4L3 16l10.4-2.6z'/><path d='M0 16h3M29 16h3M16 0v3M16 29v3'/></g></svg>");

  --витинанка:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 160 160'><g fill='%231B1A17' fill-opacity='.14'><rect x='78' y='44' width='4' height='104'/><path d='M54 148h52l-8 10H62z'/><g id='a'><path d='M79 130c-26-2-42-16-46-42 24 4 40 18 46 42z'/><path d='M79 102c-22-4-34-16-36-40 20 6 32 18 36 40z'/><path d='M79 76c-16-4-24-14-26-32 14 4 22 14 26 32z'/><circle cx='34' cy='56' r='4'/></g><use href='%23a' transform='matrix(-1 0 0 1 160 0)'/><path d='M80 6l5 13 13-5-5 13 13 5-13 5 5 13-13-5-5 13-5-13-13 5 5-13-13-5 13-5-5-13 13 5z'/></g></svg>");
  --текст:"Fixel Text","Arsenal",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  --дисплей:"KyivType Titling","Fixel Display","Arsenal",Georgia,serif;
  --голос:"KyivType Serif","Source Serif 4",Georgia,"Times New Roman",serif;
  --контраст:480;       
  --ск:16px;            
  --кнопка-тло:var(--чорнило);
  --кнопка-текст:var(--полотно);

  --мережка:linear-gradient(var(--межа-темна),var(--межа-темна)) 0 0/100% 1px no-repeat,
            linear-gradient(var(--межа-темна),var(--межа-темна)) 0 100%/100% 1px no-repeat,
            repeating-linear-gradient(90deg,var(--межа-темна) 0 1px,transparent 1px 5px) 0 50%/100% 3px no-repeat;
}

@media (prefers-color-scheme:dark){
  :root:not([data-тема="світла"]){
    color-scheme:dark;
    --полотно:#141517;--аркуш:#1D1F23;--папір:#25282D;--чорнило:#EDE6D6;--олівець:#A79F91;
    --межа:#30343A;--межа-темна:#4A4F58;--золото:#D6B45C;--золото-2:#EAD18E;--на-золоті:#17181A;--сигнал:#E48C74;
    --кнопка-тло:linear-gradient(160deg,var(--золото-2),var(--золото));--кнопка-текст:var(--на-золоті);
    --фактура:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'><g fill='none' stroke='%23EDE6D6' stroke-opacity='.055'><path d='M16 3l2.6 10.4L29 16l-10.4 2.6L16 29l-2.6-10.4L3 16l10.4-2.6z'/><path d='M0 16h3M29 16h3M16 0v3M16 29v3'/></g></svg>");
    --витинанка:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 160 160'><g fill='%23EDE6D6' fill-opacity='.13'><rect x='78' y='44' width='4' height='104'/><path d='M54 148h52l-8 10H62z'/><g id='a'><path d='M79 130c-26-2-42-16-46-42 24 4 40 18 46 42z'/><path d='M79 102c-22-4-34-16-36-40 20 6 32 18 36 40z'/><path d='M79 76c-16-4-24-14-26-32 14 4 22 14 26 32z'/><circle cx='34' cy='56' r='4'/></g><use href='%23a' transform='matrix(-1 0 0 1 160 0)'/><path d='M80 6l5 13 13-5-5 13 13 5-13 5 5 13-13-5-5 13-5-13-13 5 5-13-13-5 13-5-5-13 13 5z'/></g></svg>")}
}
:root[data-тема="темна"]{
  color-scheme:dark;
  --полотно:#141517;--аркуш:#1D1F23;--папір:#25282D;--чорнило:#EDE6D6;--олівець:#A79F91;
  --межа:#30343A;--межа-темна:#4A4F58;--золото:#D6B45C;--золото-2:#EAD18E;--на-золоті:#17181A;--сигнал:#E48C74;
  --кнопка-тло:linear-gradient(160deg,var(--золото-2),var(--золото));--кнопка-текст:var(--на-золоті);
  --фактура:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'><g fill='none' stroke='%23EDE6D6' stroke-opacity='.055'><path d='M16 3l2.6 10.4L29 16l-10.4 2.6L16 29l-2.6-10.4L3 16l10.4-2.6z'/><path d='M0 16h3M29 16h3M16 0v3M16 29v3'/></g></svg>");
  --витинанка:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 160 160'><g fill='%23EDE6D6' fill-opacity='.13'><rect x='78' y='44' width='4' height='104'/><path d='M54 148h52l-8 10H62z'/><g id='a'><path d='M79 130c-26-2-42-16-46-42 24 4 40 18 46 42z'/><path d='M79 102c-22-4-34-16-36-40 20 6 32 18 36 40z'/><path d='M79 76c-16-4-24-14-26-32 14 4 22 14 26 32z'/><circle cx='34' cy='56' r='4'/></g><use href='%23a' transform='matrix(-1 0 0 1 160 0)'/><path d='M80 6l5 13 13-5-5 13 13 5-13 5 5 13-13-5-5 13-5-13-13 5 5-13-13-5 13-5-5-13 13 5z'/></g></svg>")}


.картка,.плитка,.заява,.біб-образ,.рамка,#пал-основа .чип:has(.зразки),button.тихо,.сцн-відкрити,.паспорт,.приклад,.репліка.ші{
  --вікно:polygon(var(--ск) 0,calc(100% - var(--ск)) 0,100% var(--ск),100% 100%,0 100%,0 var(--ск));
  --кайма:polygon(evenodd,var(--ск) 0,calc(100% - var(--ск)) 0,100% var(--ск),100% 100%,0 100%,0 var(--ск),
    1px calc(var(--ск) + .4px),1px calc(100% - 1px),calc(100% - 1px) calc(100% - 1px),calc(100% - 1px) calc(var(--ск) + .4px),
    calc(100% - var(--ск) - .4px) 1px,calc(var(--ск) + .4px) 1px);
  position:relative;isolation:isolate;clip-path:var(--вікно)}
.картка::after,.плитка::after,.заява::after,.біб-образ::after,.рамка::before,#пал-основа .чип:has(.зразки)::after,
button.тихо::after,.сцн-відкрити::after,.паспорт::after,.приклад::after,.репліка.ші::after{
  content:"";position:absolute;inset:0;z-index:3;pointer-events:none;background:var(--кайма-колір,var(--межа))}
@supports (clip-path:polygon(evenodd,0 0,1px 0,1px 1px)){
  .картка::after,.плитка::after,.заява::after,.біб-образ::after,.рамка::before,#пал-основа .чип:has(.зразки)::after,
  button.тихо::after,.сцн-відкрити::after,.паспорт::after,.приклад::after,.репліка.ші::after{clip-path:var(--кайма)}
}
@supports not (clip-path:polygon(evenodd,0 0,1px 0,1px 1px)){
  .картка::after,.плитка::after,.заява::after,.біб-образ::after,.рамка::before,#пал-основа .чип:has(.зразки)::after,
  button.тихо::after,.сцн-відкрити::after,.паспорт::after,.приклад::after,.репліка.ші::after{display:none}
}


*{box-sizing:border-box}

[hidden]{display:none!important}
html{-webkit-text-size-adjust:100%;background:var(--полотно)}
body{margin:0;background:var(--полотно);color:var(--чорнило);
  font:16px/1.55 var(--текст);-webkit-font-smoothing:antialiased;padding:0 0 184px;overflow-x:hidden}
.колонка{max-width:680px;margin-inline:auto;padding:0 20px}
h1,h2,h3{font-family:var(--дисплей);font-weight:500;margin:0;letter-spacing:0;
  font-variation-settings:"CONT" var(--контраст);text-wrap:balance}
h1{font-size:34px;line-height:1.1;letter-spacing:-.005em}
h2{font-size:24px;line-height:1.2;--контраст:360}
h3{font-size:19px;line-height:1.25;--контраст:260}
p{margin:0}
a{color:var(--чорнило);text-decoration-color:var(--межа-темна);text-underline-offset:3px}
:focus-visible{outline:2px solid var(--золото);outline-offset:2px}
::selection{background:var(--золото);color:var(--на-золоті)}

svg.і{width:22px;height:22px;stroke:currentColor;fill:none;stroke-width:1.5;stroke-linecap:square;stroke-linejoin:miter;flex:0 0 auto}


.шапка{display:flex;align-items:flex-end;justify-content:flex-start;gap:10px;padding:16px 0 10px}
.знак{font:500 30px/1 var(--дисплей);font-variation-settings:"CONT" 600;letter-spacing:.01em;color:var(--чорнило);
  background:none;border:0;padding:0 0 9px;cursor:pointer;position:relative}
.знак::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--золото);
  transform-origin:left;animation:нитка .9s cubic-bezier(.2,.7,.2,1) .15s both}
@keyframes нитка{from{transform:scaleX(0)}to{transform:scaleX(1)}}

.верстат{--нитка:var(--олівець);--акцент:var(--золото);position:relative;height:236px;margin:14px 0 4px;overflow:hidden;
  background:repeating-linear-gradient(90deg,var(--межа-темна) 0 1px,transparent 1px 8px)}
.верстат::before{content:"";position:absolute;left:0;right:0;top:0;height:6px;background:var(--чорнило);opacity:.9}
.верстат .полотно{position:absolute;left:0;right:0;bottom:0;height:96%;transform:translateY(var(--зсув,75%));
  transition:transform 1.6s cubic-bezier(.2,.7,.2,1);will-change:transform}
.верстат[data-щабель="0"] .полотно{--зсув:75%}
.верстат[data-щабель="1"] .полотно{--зсув:50%}
.верстат[data-щабель="2"] .полотно{--зсув:25%}
.верстат[data-щабель="3"] .полотно{--зсув:0%}
.верстат .бердо{position:absolute;left:-4px;right:-4px;top:-3px;height:3px;background:var(--чорнило);
  animation:бити 1.15s ease-in-out infinite;will-change:transform}
@keyframes бити{0%,42%{transform:translateY(0)}50%{transform:translateY(2px)}58%,92%{transform:translateY(0)}100%{transform:translateY(2px)}}
.верстат .доріжка{position:absolute;left:0;top:-8px;width:calc(100% - 36px);height:12px;
  animation:човник 1.15s ease-in-out infinite alternate;will-change:transform}
@keyframes човник{to{transform:translateX(100%)}}
.верстат .човник{position:absolute;left:0;top:0;width:36px;height:12px;background:var(--акцент);
  clip-path:polygon(0 50%,14% 0,86% 0,100% 50%,86% 100%,14% 100%)}
.верстат .човник::after{content:"";position:absolute;left:14px;right:14px;top:4px;height:4px;background:var(--чорнило);opacity:.8}
.верстат .уток{position:absolute;left:0;right:0;top:-2px;height:2px;background:var(--нитка);will-change:transform}
.верстат .уток.л{transform-origin:left;animation:уток-л 2.3s linear infinite}
.верстат .уток.п{transform-origin:right;animation:уток-п 2.3s linear infinite}
@keyframes уток-л{0%{transform:scaleX(0)}50%{transform:scaleX(1)}50.01%,100%{transform:scaleX(0)}}
@keyframes уток-п{0%,50%{transform:scaleX(0)}100%{transform:scaleX(1)}}
.верстат .вікно{position:absolute;inset:0;overflow:hidden}
.верстат .тканина{position:absolute;left:0;right:0;top:0;height:200%;will-change:transform;
  animation:намотувати 46s linear infinite;

  background:
    repeating-linear-gradient(0deg,transparent 0 7px,var(--полотно) 7px 8px),
    repeating-conic-gradient(var(--нитка) 0 25%,transparent 0 50%) 0 0/8px 8px}
@keyframes намотувати{from{transform:translateY(-50%)}to{transform:translateY(0)}}

.верстат .смуга{position:absolute;left:0;right:0;height:14px;background:var(--чорнило)}
.верстат .смуга::before{content:"";position:absolute;inset:2px 0;background:
  repeating-linear-gradient(45deg,var(--акцент) 0 1.5px,transparent 1.5px 9px),
  repeating-linear-gradient(-45deg,var(--акцент) 0 1.5px,transparent 1.5px 9px)}
.верстат .смуга.тонка{height:4px}.верстат .смуга.тонка::before{display:none}
.верстат .смуга.акцентна{background:var(--акцент);height:3px}.верстат .смуга.акцентна::before{display:none}
.верстат.тихо .доріжка,.верстат.тихо .уток,.верстат.тихо .бердо,.верстат.тихо .тканина{animation-play-state:paused}
@media (prefers-reduced-motion:reduce){.верстат *{animation:none!important}}



.поступ{margin:8px 0 2px}
.лічба{font:400 13px/1 var(--текст);font-variant-numeric:tabular-nums;color:var(--олівець);margin-bottom:12px}
.нитка{display:grid;grid-template-columns:repeat(3,1fr);position:relative}
.нитка::before{content:"";position:absolute;left:5px;right:calc(33.4% - 5px);top:5px;height:1px;background:var(--межа-темна)}
.нитка button{min-height:44px;background:none;border:0;padding:0;text-align:left;cursor:pointer;color:var(--олівець);
  font:400 12.5px/1.3 var(--текст);position:relative;clip-path:none}
.нитка button i{display:block;width:11px;height:11px;border-radius:50%;border:1px solid var(--межа-темна);
  background:var(--полотно);margin:0 0 10px 0}
.нитка button.є i{background:var(--чорнило);border-color:var(--чорнило)}
.нитка button.тут{color:var(--чорнило);font-weight:500}
.нитка button.тут i{background:var(--золото);border-color:var(--золото);box-shadow:0 0 0 3px var(--полотно),0 0 0 4px var(--золото)}


.екран{display:none;animation:зʼява .18s ease-out both}
@keyframes зʼява{from{opacity:0}to{opacity:1}}
.вступ{padding:24px 0 10px}
.вступ h1 em{font-style:normal;color:var(--золото)}
.вступ p{color:var(--олівець);font-size:15px;margin-top:10px;max-width:30em}

.розділ{position:relative;padding:26px 0 6px;margin-top:16px}
.розділ::before{content:"";position:absolute;left:0;right:0;top:0;height:5px;background:var(--мережка);opacity:.9}
.розділ h2{margin-bottom:4px}
.підказка{color:var(--олівець);font-size:14px;line-height:1.5;margin-top:6px}
.статус{color:var(--олівець);font-size:13.5px;line-height:1.5;margin-top:8px;white-space:pre-line}
.ком-запис{margin-top:6px;font-size:13.5px;line-height:1.5;color:var(--олівець)}
.ком-запис summary{cursor:pointer;min-height:32px;display:flex;align-items:center}
.ком-запис-текст{margin:4px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}
.статус:empty{display:none}
.ряд{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:10px 0}
#сц-мета-зони-плитки[hidden]{display:none}
.мітка{font:500 20px/1.25 var(--дисплей);font-variation-settings:"CONT" 260;margin:22px 0 8px}


.вкладки{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin-top:8px;padding:8px 0 10px;position:relative}
.вкладки::before{content:"";position:absolute;left:0;right:0;top:0;height:1px;background:var(--межа)}
.вкладки button{min-height:44px;background:none;border:0;clip-path:none;padding:6px 4px 2px;color:var(--олівець);
  display:flex;flex-direction:column;align-items:center;gap:4px;font:500 11.5px/1.2 var(--текст);position:relative}
.вкладки button svg.і{width:22px;height:22px;stroke-width:1.4}
.вкладки button i{width:22px;height:22px;border-radius:50%;background:var(--олівець);color:var(--полотно);
  font:600 9px/22px var(--текст);font-style:normal;letter-spacing:.04em;text-align:center;text-transform:uppercase}
.вкладки button.тут{color:var(--чорнило)}
.вкладки button.тут i{background:var(--чорнило)}
.вкладки button.тут::after{content:"";position:absolute;left:50%;bottom:-7px;width:4px;height:4px;border-radius:50%;
  margin-left:-7px;background:var(--золото);box-shadow:6px 0 0 var(--золото)}
#смуга-профілів{display:contents}
.ряд-налаштування{justify-content:space-between}
.ряд-налаштування>span{font-size:14.5px}
#тема-кнопка{display:inline-flex;align-items:center;gap:8px}
#тема-кнопка svg.і{width:18px;height:18px}


.шапка{justify-content:space-between}
.шапка-дії{display:flex;gap:16px;padding-bottom:9px}
.шапка-дії[hidden]{display:none}
.шапка-дії button.текст{font-size:13.5px;padding:4px 0}
.шапка-дії button[hidden]{display:none}

.шапка-право{display:flex;align-items:flex-end;gap:14px}
.тема{width:44px;height:44px;border-radius:50%;padding:0;background:none;border:1px solid var(--межа-темна);color:var(--чорнило);
  display:inline-flex;align-items:center;justify-content:center;cursor:pointer;margin-bottom:4px;clip-path:none;flex:0 0 auto}
.тема svg.і{width:18px;height:18px}

.тихо-слово{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}


.ші{position:relative}
.пілюля-ші{display:flex;align-items:center;gap:10px;width:100%;text-align:left;background:var(--аркуш);border:1px solid var(--межа-темна);
  border-radius:999px;clip-path:none;padding:11px 16px;color:var(--олівець);font:400 14px/1.35 var(--текст);min-height:44px}
.пілюля-ші[hidden]{display:none}
.пілюля-ші i{flex:0 0 auto;width:4px;height:4px;border-radius:50%;background:var(--золото);box-shadow:6px 0 0 var(--золото);margin-right:6px}
.пілюля-ші span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
#ші-аркуш[hidden]{display:none}
.ші-аркуш-верх{justify-content:flex-end;margin:0 0 4px}
.ші-аркуш-верх button{padding:4px 0;font-size:12.5px}
#ші-стрічка{max-height:46vh;overflow:auto;margin:0 0 8px;padding:2px 0;overscroll-behavior:contain}
#чат-стрічка{display:flex;flex-direction:column;gap:8px}
#чат-стрічка:empty{display:none}
.репліка{max-width:88%;padding:11px 14px;font-size:15px;line-height:1.5;white-space:pre-line}
.репліка.вона{align-self:flex-end;background:var(--чорнило);color:var(--полотно);
  clip-path:polygon(0 0,100% 0,100% 100%,10px 100%,0 calc(100% - 10px))}
.репліка.ші{--ск:10px;align-self:flex-start;background:var(--аркуш);max-width:92%}
.репліка .порада-нота{display:block;margin-top:6px;font-size:12.5px;color:var(--олівець)}

.вікно-розмови,.аркуш-письма{position:relative;isolation:isolate;
  clip-path:polygon(var(--ск) 0,calc(100% - var(--ск)) 0,100% var(--ск),100% 100%,0 100%,0 var(--ск))}
.вікно-розмови::after,.аркуш-письма::after{content:"";position:absolute;inset:0;z-index:3;pointer-events:none;background:var(--межа-темна);
  clip-path:polygon(evenodd,var(--ск) 0,calc(100% - var(--ск)) 0,100% var(--ск),100% 100%,0 100%,0 var(--ск),
    1px calc(var(--ск) + .4px),1px calc(100% - 1px),calc(100% - 1px) calc(100% - 1px),calc(100% - 1px) calc(var(--ск) + .4px),
    calc(100% - var(--ск) - .4px) 1px,calc(var(--ск) + .4px) 1px)}
.чат-ввід{display:flex;gap:8px;align-items:flex-end}
.чат-ввід[hidden]{display:none}
.чат-ввід textarea{flex:1;margin:0;padding:10px 0;border:0;background:none;font:400 17px/1.4 var(--текст);color:var(--чорнило);
  resize:none;min-height:56px;max-height:160px;outline:none;box-shadow:none}
.чат-ввід textarea:focus{border:0;box-shadow:none}
.чат-ввід textarea::placeholder{color:var(--олівець);opacity:1;font-size:17px}
.чат-низ{display:flex;align-items:center;justify-content:flex-end;gap:12px;flex:0 0 auto}
.слати{width:48px;height:48px;padding:0;border-radius:50%;clip-path:none;display:inline-flex;align-items:center;justify-content:center;
  background:var(--чорнило);color:var(--полотно);flex:0 0 auto;border:1px solid var(--чорнило)}
.слати svg.і{width:22px;height:22px;stroke-width:1.8}
.слати.порожньо{background:none;border-color:var(--межа-темна);color:var(--олівець)}

.мікрофон{width:44px;height:44px;padding:0;border-radius:50%;clip-path:none;display:inline-flex;align-items:center;justify-content:center;
  background:none;color:var(--чорнило);flex:0 0 auto;border:1px solid var(--межа-темна)}
.мікрофон svg.і{width:21px;height:21px;stroke-width:1.8}
.мікрофон.слухає{background:var(--чорнило);color:var(--полотно);border-color:var(--чорнило);animation:мік-дихання 1.6s ease-in-out infinite}
@keyframes мік-дихання{0%,100%{box-shadow:0 0 0 0 var(--межа-темна)}50%{box-shadow:0 0 0 6px var(--межа)}}
@media (prefers-reduced-motion:reduce){.мікрофон.слухає{animation:none;box-shadow:0 0 0 4px var(--межа)}}

.чат-низ .мікрофон{width:48px;height:48px}
.чат-низ .мікрофон svg.і{width:22px;height:22px}
.аркуш-письма .мікрофон{width:54px;height:54px}
.аркуш-письма .мікрофон svg.і{width:24px;height:24px}

.голос-ряд{display:flex;align-items:center;gap:12px;margin:10px 0 0}
.голос-ряд .підпис-голосу{font-size:13.5px;color:var(--олівець);line-height:1.4}

.фото-речі{width:48px;height:48px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;
  border:1px solid var(--межа-темна);color:var(--олівець);cursor:pointer;flex:0 0 auto;position:relative}
.фото-речі svg.і{width:22px;height:22px;stroke-width:1.6}
.фото-речі input{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}
.фото-речі[hidden]{display:none}
.аркуш-письма .фото-речі{width:54px;height:54px}
.чат-вкладення{display:flex;gap:8px;flex-wrap:wrap}
.чат-вкладення:empty{display:none}
.вкладення{position:relative;width:64px;height:64px;flex:0 0 auto}
.вкладення img{width:64px;height:64px;object-fit:cover;display:block;border-radius:6px}
.вкладення button{position:absolute;top:-8px;right:-8px;width:26px;height:26px;padding:0;border-radius:50%;clip-path:none;
  background:var(--чорнило);color:var(--полотно);border:0;display:inline-flex;align-items:center;justify-content:center}
