.оц-фото{display:flex;flex-wrap:wrap;gap:14px;margin-top:4px}
.оц-плюс{width:64px;height:64px;display:flex;align-items:center;justify-content:center;border:1px dashed var(--межа-темна);
  border-radius:6px;font:300 30px/1 var(--текст);color:var(--олівець);background:var(--аркуш);cursor:pointer}
.оц-необов{font:400 12.5px var(--текст);color:var(--олівець);margin-left:6px}
.оц-поле .поле{margin-top:4px}
.оц-опади{margin-top:10px;gap:8px}
.оц-дія{padding:18px 0 0}
.оц-речі{margin-top:14px}
.оц-речі h3{font:600 16px var(--текст);margin:0 0 6px}
.оц-річ{display:flex;align-items:center;gap:10px;min-height:56px;padding:6px 0;border-top:1px solid var(--межа-темна)}
