.оц-річ.відкр{background:var(--полотно-2,transparent)}
.оц-мін{width:44px;height:44px;border-radius:6px;flex:0 0 auto;border:1px dashed var(--межа-темна)}
.оц-х{flex:0 0 auto;width:44px;height:44px;margin-right:-8px;border:0;background:transparent;color:var(--олівець);font-size:18px;line-height:1;cursor:pointer}
.оц-плюс-річ{display:block;width:100%;min-height:44px;margin-top:8px;border:1px dashed var(--межа-темна);border-radius:10px;background:transparent;color:inherit;font:inherit;cursor:pointer}
.оц-ред{padding:4px 0 12px}
.оц-ред-мітка{font-size:12px;color:var(--олівець);margin:8px 0 4px}
.оц-чипи{display:flex;flex-wrap:wrap;gap:6px}
.оц-слова{margin-top:14px}
.оц-слова textarea{width:100%;box-sizing:border-box;min-height:64px;font-size:16px}
.оц-слова .голос-ряд .мікрофон{width:48px;height:48px}
.оц-слова .голос-ряд .мікрофон svg.і{width:22px;height:22px}
.оц-кола{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.оц-коло{width:36px;height:36px;border-radius:50%;border:1px solid var(--межа-темна);padding:0;cursor:pointer}
.оц-коло.вибр{outline:2px solid var(--чорнило);outline-offset:2px}
.оц-дотик{display:flex;flex-wrap:wrap;gap:8px}
.оц-дотик-фото{position:relative;line-height:0}
.оц-дотик-фото img{max-height:140px;max-width:100%;border-radius:6px;cursor:crosshair}
.оц-мітка-дотику{position:absolute;border:2px solid var(--чорнило);box-shadow:0 0 0 1px #fff;border-radius:3px;pointer-events:none}
.оц-картка .оц-відповідь{font-size:17.5px}


.оц-зміни .річ .н .назва,.оц-зміни .річ .н a{display:block;overflow:visible;
  -webkit-line-clamp:unset;overflow-wrap:anywhere}
.оц-зміни .річ a{display:block;font-size:12.5px;color:var(--олівець);margin-top:3px}
.оц-не-знаю .задум{margin-top:8px}
.оц-допит{margin:10px 18px 0;padding-top:4px}
.оц-допит .репліка{margin:8px 0}
.оц-допит textarea{margin-top:6px}
.фото-репліки{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 6px}
.фото-репліки:last-child{margin:0}
.фото-репліки img{width:84px;height:84px;object-fit:cover;display:block;border-radius:6px}

.панель .чат-ввід{--ск:14px;background:var(--аркуш);padding:12px 8px 8px 16px;min-height:88px}

.аркуш-письма{--ск:18px;background:var(--аркуш) var(--фактура);margin-top:20px;padding:18px 18px 12px;min-height:250px;display:flex;flex-direction:column}
.аркуш-письма[hidden]{display:none}
#сц-лист-місце{display:flex;flex-direction:column;flex:1}
.аркуш-письма .чат-ввід{flex-direction:column;align-items:stretch;flex:1;gap:8px}
.аркуш-письма .чат-ввід textarea{font-size:18px;line-height:1.5;min-height:160px;max-height:none;padding:0}
.аркуш-письма .чат-ввід textarea::placeholder{font-size:18px}
.аркуш-письма .чат-низ{justify-content:flex-end}
.аркуш-письма .слати{width:54px;height:54px}
.аркуш-письма .слати svg.і{width:24px;height:24px}
#чат-стан{margin:6px 0 0}

.швидкі{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding:2px 20px 10px;margin:0 -20px}
.швидкі::-webkit-scrollbar{display:none}
.швидкі:empty{display:none}
.швидкі .чип{flex:0 0 auto;font-size:14px;padding:9px 14px;background:var(--полотно)}
.пс-питання{display:flex;flex-wrap:wrap;align-items:baseline;gap:0 4px;padding:12px 16px 4px;border-top:1px solid var(--межа);
  font-size:13.5px;color:var(--олівець)}
.пс-питання button{padding:2px 0;margin-left:14px}
.вето-група{margin-top:10px;width:100%}
.вето-група .назва{font-size:13px;color:var(--олівець)}
.вето-група .ряд{margin:6px 0 0}
.чип.знімний::after{content:"\00d7";margin-left:2px;color:var(--олівець)}
.чип.знімний.вибр::after{color:inherit}


.вступ#сц-вступ{padding-bottom:0}
html.широко .вступ#сц-вступ,html.широко #е-огляд .профіль-шапка{padding-top:0}
.вступ#сц-вступ h1{font-size:44px;line-height:1.05}
.розмова{margin-top:14px}
.розмова #чат-стрічка{gap:10px}
.розмова:empty{display:none}

#сц-приклади{display:flex;flex-direction:column;gap:8px;margin-top:20px}
#сц-приклади:empty{display:none}
.приклад{--ск:10px;display:block;width:100%;text-align:left;background:var(--аркуш);color:var(--чорнило);border:0;
  padding:13px 16px;font:400 15px/1.4 var(--текст);cursor:pointer}
.увага{display:flex;gap:12px;align-items:flex-start;background:var(--папір);padding:14px 16px;margin-top:14px;font-size:14px;line-height:1.5;
  clip-path:polygon(12px 0,calc(100% - 12px) 0,100% 12px,100% 100%,0 100%,0 12px)}
.увага[hidden]{display:none}
.увага svg.і{color:var(--золото);margin-top:2px}
.увага button.текст{padding:2px 0;margin-left:6px}
.паспорт{--ск:14px;background:var(--аркуш);margin-top:10px;padding:0 0 14px}
.паспорт[hidden]{display:none}
.пс-шапка{display:flex;flex-direction:column;gap:3px;padding:14px 16px 10px;background:var(--мережка);background-position:0 100%,0 100%,0 calc(100% - 2px)}
.пс-шапка b{font:500 19px/1.25 var(--дисплей);font-variation-settings:"CONT" 260}
.пс-шапка small{font-size:13px;color:var(--олівець);min-height:1em}
.ряд-паспорта{display:grid;grid-template-columns:104px 1fr auto;gap:10px;align-items:baseline;width:100%;text-align:left;
  background:none;border:0;border-top:1px solid var(--межа);clip-path:none;padding:11px 16px;color:var(--чорнило);font:400 15px/1.4 var(--текст)}
.ряд-паспорта>span{font-size:13px;color:var(--олівець)}
.ряд-паспорта>b{font-weight:500;min-width:0;overflow-wrap:anywhere}
.ряд-паспорта>b.типово,.ряд-паспорта>b>span.типово{font-weight:400;color:var(--олівець)}
.ряд-паспорта::after{content:"›";color:var(--олівець);font-size:18px;line-height:1;justify-self:end}
.ряд-паспорта.відкрито{background:var(--папір)}
.ряд-паспорта[hidden]{display:none}
.пс-шапка+.ряд-паспорта{border-top:0}

.редактор[hidden]{display:none}
.редактор .плитки{margin-top:12px}
.редактор .умови{margin-top:8px}
.редактор .дрібні{margin-top:12px}
.редактор .поле:has(>select){margin-top:8px}
.пс-дія{padding:14px 16px 0}
.пс-дія button.головна{width:100%;margin:0;padding:15px 20px;font-size:15.5px;background:var(--кнопка-тло);color:var(--кнопка-текст);
  clip-path:polygon(10px 0,calc(100% - 10px) 0,100% 10px,100% 100%,0 100%,0 10px)}
.пс-дрібні{display:flex;justify-content:center;gap:18px;padding-top:10px}
.пс-дрібні button.текст{font-size:13px;padding:4px 0}
#сц-рукою-ряд{margin:12px 0 0}
.сц-збер .поле{margin-top:0}
.сц-збер[hidden]{display:none}
button.назад{padding:14px 0 0;font-size:14px}
.сцн{display:grid;grid-template-columns:1fr auto;gap:0 10px;align-items:center;margin-top:8px}
.сцн-відкрити{--ск:12px;display:flex;flex-direction:column;gap:2px;width:100%;text-align:left;background:var(--аркуш);border:0;
  padding:12px 14px;color:var(--чорнило);font:400 14px/1.35 var(--текст);cursor:pointer}
.сцн-відкрити b{font:500 18px/1.25 var(--дисплей);font-variation-settings:"CONT" 260}
.сцн-відкрити small{font-size:12px;color:var(--олівець)}
.сцн-відкрити.тут{--кайма-колір:var(--золото)}
.сцн-геть{padding:8px 0;font-size:12.5px;color:var(--олівець);text-decoration-color:var(--межа-темна);white-space:nowrap}
#біб-назад-ряд[hidden]{display:none}


.заслона{position:fixed;inset:0;background:rgba(27,26,23,.38);z-index:40}
.заслона[hidden]{display:none}
:root[data-тема="темна"] .заслона{background:rgba(0,0,0,.55)}
.аркуш{position:fixed;left:0;right:0;bottom:0;z-index:50;background:var(--аркуш);
  clip-path:polygon(16px 0,calc(100% - 16px) 0,100% 16px,100% 100%,0 100%,0 16px);
  padding:0 20px calc(16px + env(safe-area-inset-bottom));max-height:88vh;overflow:auto;overscroll-behavior:contain;
  animation:підняти .22s cubic-bezier(.2,.7,.2,1) both}
.аркуш[hidden]{display:none}
@keyframes підняти{from{transform:translateY(24px);opacity:0}to{transform:none;opacity:1}}
.аркуш .ручка{width:36px;height:3px;background:var(--межа-темна);margin:10px auto 0}
.аркуш-шапка{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:16px 0 6px}
.аркуш-шапка h2{font-size:24px;line-height:1.15}
.аркуш-шапка button.текст{font-size:14px;padding:4px 0}
.аркуш-шапка button[hidden]{display:none}
.аркуш .готово{margin-top:18px;width:100%;padding:15px 20px;font-size:15.5px}
.аркуш .готово[hidden]{display:none}
#аркуш-тіло>.редактор{padding:0}
#аркуш-тіло .умови{grid-template-columns:1fr 1fr}
#аркуш-тіло .пілюля{min-width:0;padding:10px 10px;gap:8px}
#аркуш-тіло .пілюля label{min-width:0}
#аркуш-тіло .пілюля input{width:44px}
#аркуш-тіло .сцена .площина{right:0}
#аркуш-тіло>details{margin-top:0}
#аркуш-тіло>details>summary{display:none}
#аркуш-тіло .розділ{padding-top:0;margin-top:0}
#аркуш-тіло .розділ::before{display:none}
#аркуш-тіло .розділ>h2{display:none}
#аркуш-тіло .сцена{margin-top:4px}

#аркуш :focus-visible{outline:2px solid var(--золото);outline-offset:2px}
#аркуш button:focus-visible{outline-offset:-3px}
html.аркуш-відкрито{overflow:hidden}


.профіль-шапка{display:flex;align-items:center;gap:14px;padding:22px 0 4px}
.профіль-шапка .ініціали{flex:0 0 auto;width:56px;height:56px;border-radius:50%;background:var(--чорнило);color:var(--полотно);
  font:600 16px/56px var(--текст);text-align:center;letter-spacing:.06em;text-transform:uppercase}
.профіль-шапка h1{font-size:34px;line-height:1.05}
.профіль-шапка .статус{margin-top:4px}
#е-огляд .мітка{margin:22px 0 8px}
.список{--ск:14px;background:var(--аркуш);padding:2px 0;position:relative;isolation:isolate;
  clip-path:polygon(var(--ск) 0,calc(100% - var(--ск)) 0,100% var(--ск),100% 100%,0 100%,0 var(--ск))}
.список::after{content:"";position:absolute;inset:0;z-index:3;pointer-events:none;background:var(--межа);
  clip-path:polygon(evenodd,var(--ск) 0,calc(100% - var(--ск)) 0,100% var(--ск),100% 100%,0 100%,0 var(--ск),
    1px calc(var(--ск) + .4px),1px calc(100% - 1px),calc(100% - 1px) calc(100% - 1px),calc(100% - 1px) calc(var(--ск) + .4px),
    calc(100% - var(--ск) - .4px) 1px,calc(var(--ск) + .4px) 1px)}
.рядок{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr) auto;gap:12px;align-items:center;width:100%;text-align:left;
  background:none;border:0;border-top:1px solid var(--межа);clip-path:none;padding:14px 16px;color:var(--чорнило);font:400 15px/1.35 var(--текст)}
.список .рядок:first-child{border-top:0}
.рядок .н{display:flex;flex-direction:column;gap:3px;min-width:0}
.рядок .н b{font-weight:500;font-size:15.5px}
.рядок .н small{font-size:13px;color:var(--олівець)}
.рядок::after{content:"›";color:var(--олівець);font-size:20px;line-height:1}
.рядок .прев{font:400 14px/1.3 var(--текст);color:var(--олівець);text-align:right;justify-self:end;min-width:0;overflow-wrap:anywhere}
.рядок .прев.число{font-weight:500;color:var(--чорнило);font-variant-numeric:tabular-nums;letter-spacing:.02em;white-space:nowrap}
.рядок .прев.число small{color:var(--олівець);font-weight:400;margin-left:6px;font-size:13px}
.рядок .прев.брак{color:var(--золото);font-weight:500;font-size:13px}
.рядок .прев .зразки{display:inline-flex}
.рядок .прев .зразки i{display:inline-block;width:22px;height:22px;border:1px solid rgba(0,0,0,.12)}
.рядок .прев .зразки i+i{border-left:0}
.рядок .прев.фото{display:inline-flex;gap:4px}
.рядок .прев.фото i{display:inline-block;width:26px;height:34px;background:var(--папір) var(--фактура);clip-path:polygon(6px 0,100% 0,100% 100%,0 100%,0 6px)}
.рядок .прев.фото i.є{background:var(--папір) var(--фактура) center/cover no-repeat}




.розширені{display:grid;grid-template-columns:1fr 1fr;gap:10px 22px;margin-top:14px}
.розширені label{display:grid;grid-template-columns:auto auto 1fr;align-items:baseline;gap:0 8px}
.розширені span{font:400 13px var(--текст);color:var(--олівець)}
.розширені input{width:60px;padding:3px 0;font:500 17px/1.2 var(--текст);font-variant-numeric:tabular-nums;text-align:right;
  border-bottom:1px solid var(--межа-темна)}
.розширені b{font:400 11px var(--текст);color:var(--олівець)}
.розширені i{grid-column:1/-1;font:400 11px/1.4 var(--текст);font-style:normal;color:var(--олівець);opacity:.8;margin-top:2px}
#мр-розширені{margin-top:18px}
#мр-розширені[hidden]{display:none}
#мр-розширені>summary{font-size:15px}
#мр-розширені>.розділ{margin-top:12px}


html[data-режим="старт"] .лише-профіль{display:none}
html:not([data-режим="старт"]) .лише-старт{display:none}


.сцена{position:relative;aspect-ratio:1/1.06;margin:8px 0 0}
.сцена .площина{position:absolute;right:-20px;top:6%;width:60%;height:46%;z-index:0;
  background:var(--фактура),var(--папір);clip-path:polygon(9% 0,91% 0,100% 12%,100% 100%,0 100%,0 12%)}
.сцена .слот-портрет{position:absolute;right:6%;top:0;width:56%;z-index:2}
.сцена .слот-зріст{position:absolute;left:0;bottom:0;width:43%;z-index:3}
.слот{position:relative;isolation:isolate;display:block;width:100%;overflow:hidden;cursor:pointer;
  background:var(--фактура),var(--аркуш);clip-path:var(--вікно)}
.слот::after{content:"";position:absolute;inset:0;z-index:3;pointer-events:none;background:var(--межа-темна);clip-path:var(--кайма)}

.слот.арка{aspect-ratio:3/4.1;
  --вікно:polygon(17% 0,83% 0,100% 15%,100% 100%,0 100%,0 15%);
  --кайма:polygon(evenodd,17% 0,83% 0,100% 15%,100% 100%,0 100%,0 15%,
    1px calc(15% + .5px),1px calc(100% - 1px),calc(100% - 1px) calc(100% - 1px),calc(100% - 1px) calc(15% + .5px),
    calc(83% - .6px) 1px,calc(17% + .6px) 1px)}
.слот.полароїд{aspect-ratio:3/4.8;
  --вікно:polygon(15% 0,85% 0,100% 7%,100% 100%,0 100%,0 7%);
  --кайма:polygon(evenodd,15% 0,85% 0,100% 7%,100% 100%,0 100%,0 7%,
    1px calc(7% + .5px),1px calc(100% - 1px),calc(100% - 1px) calc(100% - 1px),calc(100% - 1px) calc(7% + .5px),
    calc(85% - .6px) 1px,calc(15% + .6px) 1px)}
.слот img{width:100%;height:100%;object-fit:cover;display:block}
.слот.полароїд img{object-fit:contain;background:var(--папір)}
.слот .порожньо{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;
  gap:10px;text-align:center;color:var(--олівець);font:500 13px/1.35 var(--текст);padding:14px}
.слот .порожньо b{display:flex;width:36px;height:36px;border-radius:50%;border:1px solid var(--межа-темна);
  align-items:center;justify-content:center;color:var(--чорнило);background:var(--аркуш)}
.слот input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}
.слот .геть{position:absolute;right:10px;bottom:10px;width:28px;height:28px;border-radius:50%;padding:0;clip-path:none;
  background:var(--аркуш);border:1px solid var(--межа-темна);color:var(--олівець);display:flex;align-items:center;justify-content:center;z-index:2}
.слот.полароїд .геть{right:auto;left:8px;bottom:8px;width:24px;height:24px}
.слот .геть svg{width:14px;height:14px}
.підпис-фото{display:flex;justify-content:space-between;font:400 13px/1.35 var(--текст);color:var(--олівець);margin-top:10px}


.поле{display:block;margin:16px 0 0}
.поле>span{display:block;font:400 13px/1.35 var(--текст);color:var(--олівець);margin:0 0 4px}
.поле-назва{display:block;font:500 18px/1.25 var(--дисплей);font-variation-settings:"CONT" 260;color:var(--чорнило);margin:0 0 8px}
input[type=text],input[type=number],select,textarea{
  width:100%;background:transparent;color:var(--чорнило);border:0;border-bottom:1px solid var(--межа-темна);
  border-radius:0;padding:10px 0;font:17px/1.4 var(--текст);-webkit-appearance:none;appearance:none}
input[type=file]{min-height:24px}
input[type=number]{font-variant-numeric:tabular-nums}
input::placeholder,textarea::placeholder{color:var(--олівець);opacity:1}
select{background-image:linear-gradient(45deg,transparent 50%,var(--олівець) 50%),
  linear-gradient(135deg,var(--олівець) 50%,transparent 50%);
  background-position:calc(100% - 12px) 55%,calc(100% - 7px) 55%;
  background-size:5px 5px;background-repeat:no-repeat;padding-right:28px}
select option{color:var(--чорнило);background:var(--аркуш)}
textarea{min-height:72px;resize:vertical;line-height:1.5}
textarea[readonly]{color:var(--олівець);font-size:13px;background:var(--аркуш);border:1px solid var(--межа);padding:10px}
textarea:not([readonly]).коробка{background:var(--аркуш);border:1px solid var(--межа);padding:12px}
input:focus,select:focus,textarea:focus{outline:none;border-bottom-color:var(--золото);box-shadow:0 1px 0 var(--золото)}
textarea.коробка:focus{border-color:var(--золото);box-shadow:none}
.згода{display:flex;gap:10px;align-items:flex-start;margin-top:18px;font-size:14.5px;line-height:1.45}
.згода input{width:24px;height:24px;flex:0 0 auto;margin:2px 0 0;accent-color:var(--чорнило)}
.пара{display:flex;gap:16px}
.пара>*{flex:1;min-width:0}

.поле:has(>select){background:var(--аркуш);border:1px solid var(--межа);padding:10px 14px 6px;margin-top:12px}
.поле:has(>select)>span{margin-bottom:0}
.поле>select{border-bottom:0;padding:4px 28px 6px 0;font:500 17px/1.3 var(--текст)}
.дрібні .поле:has(>select){margin-top:0}


button{font:500 15px/1 var(--текст);border:1px solid transparent;padding:14px 20px;
  background:var(--чорнило);color:var(--полотно);cursor:pointer;border-radius:0;
  clip-path:polygon(8px 0,calc(100% - 8px) 0,100% 8px,100% 100%,0 100%,0 8px)}
button:active{opacity:1}
button:focus-visible{outline-offset:-3px}
button.тихо{min-height:44px;--ск:8px;background:transparent;color:var(--чорнило);border:0;padding:12px 16px;font-size:14px;--кайма-колір:var(--межа-темна)}
button.текст{min-height:44px;background:none;border:0;color:var(--чорнило);padding:8px 0;font-size:14px;clip-path:none;
  text-decoration:underline;text-decoration-color:var(--золото);text-decoration-thickness:1px;text-underline-offset:4px}
button.мал{min-height:44px;padding:10px 14px;font-size:14px}
button:disabled{opacity:.45;cursor:default}
button.зі-стрілкою{display:inline-flex;align-items:center;justify-content:center;gap:10px}
details.розкривач{margin-top:14px}
summary{min-height:24px}
details.розкривач summary{cursor:pointer;font-size:14px;color:var(--чорнило);list-style:none;
  text-decoration:underline;text-decoration-color:var(--золото);text-underline-offset:4px}
details.розкривач summary::-webkit-details-marker{display:none}
details.розкривач summary::after{content:" ▾";color:var(--олівець);text-decoration:none}
details.розкривач[open] summary::after{content:" ▴"}


.чип{min-height:44px;display:inline-flex;align-items:center;gap:8px;border:1px solid var(--межа-темна);border-radius:999px;
  padding:9px 14px;font-size:14px;line-height:1.3;background:var(--аркуш);cursor:pointer;user-select:none;
  color:var(--чорнило);position:relative;transition:background .15s,color .15s,border-color .15s}
.чип.вибр{border-color:var(--чорнило);background:var(--чорнило);color:var(--полотно);padding-left:24px}
.чип.вибр::before{content:"";position:absolute;left:11px;top:50%;margin-top:-2px;width:4px;height:4px;
  border-radius:50%;background:currentColor;box-shadow:6px 0 0 currentColor}

.чип.ок.вибр{background:var(--золото);border-color:var(--золото);color:var(--на-золоті)}
.чип .зразки{display:inline-flex}
.чип .зразки i{display:inline-block;width:14px;height:14px;border:1px solid rgba(0,0,0,.15)}
.чип .зразки i+i{border-left:0}


#сц-губи-блок .чип .зразки i{width:20px;height:20px;border-radius:50%}
#сц-губи-блок .помада-рядок{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 10px;margin:8px 0}
#сц-губи-блок .помада-причина{font-size:12px;color:var(--олівець);flex:1 1 100%;margin:0 0 0 4px}
button.як-слово{min-height:24px;background:none;border:0;padding:0;font:inherit;color:var(--олівець);
  text-decoration:underline;cursor:pointer}


.плитки{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:12px}
.плитка{--ск:10px;background:var(--аркуш);border:0;padding:16px 8px 12px;
  display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:8px;text-align:center;
  min-height:100px;cursor:pointer;color:var(--чорнило);font:400 13px/1.25 var(--текст);transition:background .15s,color .15s}
.плитка svg.і{width:24px;height:24px;stroke-width:1.4}

#сц-відчуття-плитки .плитка{padding:11px 6px 9px;min-height:0}
.плитка .н{font:500 13px/1.25 var(--текст)}
.плитка small{display:block;font:400 11px/1.3 var(--текст);color:var(--олівець);margin-top:-4px}
.плитка.вибр{background:var(--чорнило);color:var(--полотно);--кайма-колір:var(--чорнило)}
.плитка.вибр small{color:inherit;opacity:.7}
.плитка.вибр::before{content:"";position:absolute;left:10px;top:12px;width:4px;height:4px;border-radius:50%;
  background:currentColor;box-shadow:6px 0 0 currentColor;z-index:2}
.умови{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}
.пілюля{display:flex;align-items:center;gap:10px;background:var(--аркуш);border:1px solid var(--межа);padding:10px 12px}
.пілюля svg.і{color:var(--олівець)}
.пілюля label{flex:1;font:400 13px var(--текст);color:var(--олівець)}
.пілюля input{width:58px;border:0;padding:2px 0;font:500 19px/1.2 var(--текст);font-variant-numeric:tabular-nums;text-align:right;background:none}
.пілюля b{font:400 13px var(--текст);color:var(--олівець)}
.дрібні{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:6px}
.візьмемо{display:flex;gap:10px;align-items:flex-start;margin-top:16px;font-size:13.5px;color:var(--олівець)}
.візьмемо::before{content:"";width:4px;height:4px;border-radius:50%;background:var(--золото);box-shadow:7px 0 0 var(--золото);
  margin:9px 8px 0 0;flex:0 0 auto}


.св-група{display:grid;grid-template-columns:104px 1fr;gap:12px;align-items:center;margin-top:10px}
.св-назва{font-size:13px;color:var(--олівець);line-height:1.3}
.св-ряд{display:flex;gap:5px}
.св{flex:1;min-width:0}
.св i{display:block;height:42px;border:1px solid rgba(0,0,0,.1)}


.крокі{position:relative;margin-top:6px}
.крокі svg{width:100%;height:auto;display:block}

.анотації{position:absolute;left:56%;top:0;width:44%;aspect-ratio:.44/1.0556}
.ан{position:absolute;left:0;right:14px;display:flex;align-items:baseline;gap:8px;transform:translateY(-50%)}
.ан span{font:400 13px var(--текст);color:var(--олівець);width:52px;flex:0 0 auto}
.ан input{width:66px;flex:0 0 auto;padding:3px 0;font:500 19px/1.2 var(--текст);font-variant-numeric:tabular-nums;text-align:right;
  border-bottom:1px solid var(--межа-темна)}
.ан b{font:400 11px var(--текст);color:var(--олівець)}





.диптих{display:flex;overflow:hidden;border:1px solid var(--межа);margin-top:10px}
.стулка{flex:1;position:relative;cursor:pointer;padding:0;background:none;border:0;border-radius:0;display:block;color:inherit;clip-path:none}
.стулка .поле-тло{height:200px;display:flex;align-items:center;justify-content:center}
.стулка .вікно{width:132px;height:150px;overflow:hidden;display:block;
  clip-path:polygon(18% 0,82% 0,100% 16%,100% 100%,0 100%,0 16%)}
.стулка .вікно img{width:100%;height:100%;object-fit:cover;display:block}
.стулка .назва{display:block;text-align:center;padding:11px 6px;font:500 14px/1.3 var(--текст);
  color:var(--чорнило);background:var(--аркуш);border-top:1px solid var(--межа)}
.стулка[aria-pressed="true"] .назва{background:var(--чорнило);color:var(--полотно)}
.диптих .стулка+.стулка{border-left:1px solid var(--межа)}
.однаково{display:block;width:100%;text-align:center;margin-top:2px}
.кадр{display:flex;gap:12px;align-items:center;margin:8px 0}
.кадр span{font-size:12.5px;color:var(--олівець);min-width:78px}
.кадр input[type=range]{flex:1;accent-color:var(--чорнило);height:22px;border:0}

.порожньо-текст,#біб-стан:not(:empty){padding:20px 100px 20px 16px;color:var(--олівець);font-size:14px;line-height:1.5;margin-top:12px;
  background:var(--витинанка) right 14px center/78px no-repeat,var(--фактура),var(--папір);
  clip-path:polygon(12px 0,calc(100% - 12px) 0,100% 12px,100% 100%,0 100%,0 12px);min-height:96px}


.стрічка{display:flex;gap:4px;height:16px;margin:14px 0 4px}
.стрічка i{flex:1;border:1px solid rgba(0,0,0,.08)}
.стрічка i.база{flex:2.4}
.стрічка i.порожня{border:1px dashed var(--межа-темна);background:none}
.стрічка-підпис{font-size:13px;color:var(--олівець)}

#пал-основа,#пал-основа details>.ряд{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0 0}
#пал-основа details{grid-column:1/-1;width:100%;margin-top:6px}
#пал-основа details>summary{font-size:14px;color:var(--чорнило);cursor:pointer;list-style:none;padding:8px 0;
  text-decoration:underline;text-decoration-color:var(--золото);text-underline-offset:4px}
#пал-основа details>summary::-webkit-details-marker{display:none}
#пал-основа details>summary::after{content:" ▾";color:var(--олівець)}
#пал-основа details[open]>summary::after{content:" ▴"}
#пал-основа .чип:not(:has(.зразки)){grid-column:1/-1;justify-content:center;padding:12px}
#пал-основа .чип:has(.зразки){--ск:10px;display:flex;flex-direction:column;align-items:stretch;gap:0;padding:0 10px 9px;border-radius:0;border:0;
  background:var(--аркуш);color:var(--чорнило);font-size:12.5px;line-height:1.25;text-align:left;overflow:hidden}
#пал-основа .чип:has(.зразки) .зразки{display:flex;flex-direction:column;width:calc(100% + 20px);margin:0 -10px 8px}
#пал-основа .чип:has(.зразки) .зразки i{display:block;width:100%;height:64px;border:0}
#пал-основа .чип.вибр:has(.зразки){background:var(--аркуш);color:var(--чорнило);padding-left:10px;--кайма-колір:var(--чорнило)}
#пал-основа .чип.вибр:has(.зразки)::before{left:auto;right:9px;top:9px;margin:0;z-index:2;background:var(--аркуш);box-shadow:6px 0 0 var(--аркуш)}

#пал-основа details>.ряд .чип:has(.зразки) .зразки i{height:48px}
#пал-схема{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:12px 0 0}
#пал-схема .чип:not(:has(.зразки)){grid-column:1/-1;justify-content:center;padding:12px}
#пал-схема .чип:has(.зразки){display:flex;flex-direction:column;align-items:stretch;gap:0;padding:0 10px 9px;border-radius:0;font-size:12.5px;line-height:1.25;overflow:hidden}
#пал-схема .чип:has(.зразки) .зразки{display:flex;width:calc(100% + 20px);margin:0 -10px 8px}
#пал-схема .чип:has(.зразки) .зразки i{flex:1;height:40px;border:0}
#пал-схема .чип:has(.зразки) .зразки i+i{border-left:1px solid rgba(0,0,0,.1)}
#пал-схема .чип.вибр:has(.зразки){background:var(--аркуш);color:var(--чорнило);border-color:var(--чорнило);box-shadow:inset 0 0 0 1px var(--чорнило);padding-left:10px}
#пал-схема .чип.вибр:has(.зразки)::before{left:auto;right:9px;top:9px;margin:0;z-index:1;background:var(--чорнило);box-shadow:6px 0 0 var(--чорнило)}

#пал-схема .чип.рідший{border-color:var(--межа)}
#пал-схема .чип.рідший.вибр{border-color:var(--чорнило)}

.чип.стилістка{border-color:var(--чорнило);box-shadow:inset 0 0 0 1px var(--чорнило)}
.чип.стилістка.вибр{box-shadow:none}

#пал-основа .чип.стилістка:has(.зразки){--кайма-колір:var(--чорнило)}
#пал-рідші{margin:10px 0 0;display:flex;flex-direction:column;gap:6px}
#пал-рідші:empty{display:none}
#пал-рідші .рідший-рядок{color:var(--олівець);font-size:13px;line-height:1.45}
#пал-рідші .рідший-рядок b{color:var(--чорнило);font-weight:500}
#пал-гама .ряд{gap:6px}


@property --чисто{syntax:"<percentage>";inherits:false;initial-value:0%}
#рамки{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0 6px}
.рамка{--ск:12px;aspect-ratio:3/4.2;background:var(--фактура),var(--аркуш);overflow:hidden}
.рамка span{display:none}
.рамка::after{content:"";position:absolute;inset:-4px;z-index:2;pointer-events:none;
  background-color:var(--полотно);
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='т'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/><feComponentTransfer><feFuncA type='table' tableValues='0 .5'/></feComponentTransfer></filter><rect width='160' height='160' filter='url(%23т)'/></svg>");
  --чисто:0%;opacity:.96;
  -webkit-mask-image:radial-gradient(circle at 50% 8%,transparent var(--чисто),#000 calc(var(--чисто) + 40%));
  mask-image:radial-gradient(circle at 50% 8%,transparent var(--чисто),#000 calc(var(--чисто) + 40%));
  transition:opacity .9s ease-out,--чисто 1.4s ease-out}
#рамки[data-щабель="1"] .рамка::after{--чисто:34%;opacity:.9}
#рамки[data-щабель="2"] .рамка::after{--чисто:72%;opacity:.8}
#рамки[data-щабель="3"] .рамка::after{--чисто:120%;opacity:0}

.стани{display:grid;grid-template-columns:auto 1fr;gap:9px 18px;align-items:center;margin:6px 0 16px}
.стани i{width:11px;height:11px;border-radius:50%;border:1px solid var(--межа-темна);background:var(--полотно)}
.стани span{font-size:13px;color:var(--олівець)}
.стани i.було{background:var(--чорнило);border-color:var(--чорнило)}
.стани i.тут{background:var(--золото);border-color:var(--золото);box-shadow:0 0 0 3px var(--полотно),0 0 0 4px var(--золото)}
.стани span.тут{color:var(--чорнило);font-weight:500}
.мета{display:flex;gap:6px;justify-content:space-between;padding:14px 0;position:relative}
.мета::before,.мета::after{content:"";position:absolute;left:0;right:0;height:5px;background:var(--мережка);opacity:.9}
.мета::before{top:0}.мета::after{bottom:0}
