  .аркуш{left:50%;right:auto;bottom:auto;top:50%;transform:translate(-50%,-50%);width:min(600px,92vw);max-height:86vh;padding:0 28px 26px;
    clip-path:polygon(16px 0,calc(100% - 16px) 0,100% 16px,100% calc(100% - 16px),calc(100% - 16px) 100%,16px 100%,0 calc(100% - 16px),0 16px);
    animation:зʼява .18s ease-out both}
  .аркуш .ручка{display:none}
  .аркуш-шапка{padding-top:26px}
  .сцена{max-width:520px}
  #рамки{gap:14px}
  #біб-список{display:grid;grid-template-columns:1fr 1fr;gap:10px}

  .картка{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:8px;align-items:start}
  .картка>*{grid-column:2}
  .картка>.к-шапка,.картка>.не-вийшло,.картка>.змінна-пара,.картка>.полотно{grid-column:1/-1}
  .картка>.колаж-поле{grid-column:1;grid-row:2/span 40}
}
@media (min-width:1180px){
  body{grid-template-columns:232px minmax(0,680px) 320px}
  .правий{display:block;grid-column:3;position:sticky;top:24px;align-self:start;max-height:calc(100vh - 48px);overflow:auto;padding-top:26px}
  .правий[hidden]{display:none}
  .правий .паспорт{margin-top:0}
  .правий .увага{margin:0 0 12px}
  .правий #ф-блок .сцена{max-width:none}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none !important;transition:none !important}
}

@media (forced-colors:active){
  #др-блок .чип[aria-pressed="true"]{text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:3px}
}

input:focus-visible,select:focus-visible,textarea:focus-visible{
  outline:2px solid var(--золото);outline-offset:2px}
label:has(input:focus-visible),.слот:has(input:focus-visible){
  outline:2px solid var(--золото);outline-offset:-3px}
.лише-читач{position:absolute;width:1px;height:1px;padding:0;margin:-1px;
  overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}

